package ajstrick81.morphe.extension.twitchatv.ads;

/**
 * A ~2s black (H.264) + silent (AAC) MPEG-TS segment, generated with ffmpeg
 * (640x360, low bitrate). Served in place of Twitch stitched-ad segments so the
 * player timeline ADVANCES through the ad (instead of stalling on an empty
 * playlist), letting the ad complete server-side and content resume. Embedded as
 * Base64 to avoid shipping a binary asset.
 */
final class BlankSegment {
    private BlankSegment() {}

    /** MPEG-TS packet size. */
    private static final int TS_PKT = 188;
    /** 33-bit PTS/DTS/PCR-base mask. */
    private static final long TS_33 = 0x1FFFFFFFFL;

    /**
     * Returns a copy of the blank segment with every PTS, DTS and PCR-base shifted
     * forward by {@code ticks} (90 kHz units).
     *
     * <p>Twitch stitches a whole ad break as ONE continuous timeline after a single
     * {@code #EXT-X-DISCONTINUITY} (segment N starts where N-1 ended). We serve the
     * same ~2 s blank for every ad segment, so without this shift the pod timeline
     * would repeat 0-2s, 0-2s, … — non-monotonic at each boundary, which makes
     * hls.js stall (then jump) on resume. Shifting segment k by k·(segment duration)
     * restores the continuous monotonic timeline hls.js expects, so the blanks play
     * through smoothly. PID-agnostic: any PES carries PTS/DTS, any adaptation field
     * with the PCR flag carries a PCR; PAT/PMT payloads have no {@code 00 00 01}
     * PES start code so they are left untouched. Fails safe — on any parse issue it
     * returns the un-shifted bytes.
     */
    static byte[] shift(byte[] src, long ticks) {
        if (ticks == 0 || src == null || src.length < TS_PKT) return src;
        byte[] d = src.clone();
        try {
            for (int p = 0; p + TS_PKT <= d.length; p += TS_PKT) {
                if ((d[p] & 0xFF) != 0x47) return src; // lost sync — bail, serve original
                boolean pusi = (d[p + 1] & 0x40) != 0;
                int afc = (d[p + 3] >> 4) & 0x3;
                int payload = p + 4;
                if (afc == 2 || afc == 3) {
                    int afLen = d[p + 4] & 0xFF;
                    if (afLen > 0) {
                        int flags = d[p + 5] & 0xFF;
                        if ((flags & 0x10) != 0) shiftPcr(d, p + 6, ticks); // PCR_flag
                    }
                    payload = p + 5 + afLen;
                }
                if ((afc == 1 || afc == 3) && pusi && payload + 14 <= d.length
                        && (d[payload] & 0xFF) == 0x00 && (d[payload + 1] & 0xFF) == 0x00
                        && (d[payload + 2] & 0xFF) == 0x01) {
                    int ptsDts = (d[payload + 7] >> 6) & 0x3;
                    if ((ptsDts & 0x2) != 0) shiftTs(d, payload + 9, ticks);   // PTS
                    if (ptsDts == 0x3) shiftTs(d, payload + 14, ticks);        // DTS
                }
            }
            return d;
        } catch (Throwable t) {
            return src;
        }
    }

    /** Adds {@code ticks} to a 5-byte PTS/DTS field at {@code i}, preserving prefix/markers. */
    private static void shiftTs(byte[] d, int i, long ticks) {
        long v = (((long) (d[i] & 0x0E)) << 29)
               | (((long) (d[i + 1] & 0xFF)) << 22)
               | (((long) (d[i + 2] & 0xFE)) << 14)
               | (((long) (d[i + 3] & 0xFF)) << 7)
               | (((long) (d[i + 4] & 0xFE)) >> 1);
        v = (v + ticks) & TS_33;
        int prefix = d[i] & 0xF0; // '0010'/'0011'/'0001' + high nibble
        d[i]     = (byte) (prefix | ((v >> 30) & 0x7) << 1 | 0x1);
        d[i + 1] = (byte) ((v >> 22) & 0xFF);
        d[i + 2] = (byte) (((v >> 15) & 0x7F) << 1 | 0x1);
        d[i + 3] = (byte) ((v >> 7) & 0xFF);
        d[i + 4] = (byte) ((v & 0x7F) << 1 | 0x1);
    }

    /** Adds {@code ticks} to the 33-bit PCR base (6-byte PCR at {@code i}); extension untouched. */
    private static void shiftPcr(byte[] d, int i, long ticks) {
        long base = (((long) (d[i] & 0xFF)) << 25)
                  | (((long) (d[i + 1] & 0xFF)) << 17)
                  | (((long) (d[i + 2] & 0xFF)) << 9)
                  | (((long) (d[i + 3] & 0xFF)) << 1)
                  | (((long) (d[i + 4] & 0x80)) >> 7);
        base = (base + ticks) & TS_33;
        d[i]     = (byte) ((base >> 25) & 0xFF);
        d[i + 1] = (byte) ((base >> 17) & 0xFF);
        d[i + 2] = (byte) ((base >> 9) & 0xFF);
        d[i + 3] = (byte) ((base >> 1) & 0xFF);
        d[i + 4] = (byte) (((base & 0x1) << 7) | (d[i + 4] & 0x7F));
    }

    static final String TS_BASE64 =
        "" +
        "";
}
